const args = $input.first().json;
if (!args.pregunta_usuario || String(args.pregunta_usuario).trim() === '') {
  return [{ json: { status: 'ERROR', message_to_agent: 'Faltó pregunta_usuario.', _skip: true } }];
}
return [{ json: args }];

// v2 — F1+F7: filtra records vacíos + scoring robusto.
// F7: tokeniza query y keywords, normaliza acentos, stemming simple (prefix matching),
// categoria_hint solo da BOOST cuando ya hay match real de keywords (no como condición suficiente),
// threshold >= 2 puntos de keyword/pregunta match (sin contar boost de categoria).

const faqs = $input.all()
  .map(i => i.json)
  .filter(f => f && f.id && f['Pregunta']);
const args = $('Execute Workflow Trigger').first().json;
const query = String(args.pregunta_usuario || '');
const categoria = String(args.categoria_hint || '');

function normalize(t) {
  return String(t || '')
    .toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '');
}

function tokenize(text) {
  return normalize(text)
    .split(/[\s,;\-_¿?¡!.]+/)
    .map(t => t.trim())
    .filter(t => t.length >= 3);
}

// Stemming simple: para palabras >5 chars, devuelve los primeros (n-2) chars.
// "reparar" → "repar", "reparan" → "repar", "rompió" → "romp" (normalizado), "rompio" → "romp".
function stem(t) {
  if (t.length <= 5) return t;
  return t.slice(0, t.length - 2);
}

function matchTokens(qTokens, kTokens) {
  for (const k of kTokens) {
    const ks = stem(k);
    for (const q of qTokens) {
      const qs = stem(q);
      if (q === k || qs === ks) return true;
      if (ks.length >= 4 && q.includes(ks)) return true;
      if (qs.length >= 4 && k.includes(qs)) return true;
    }
  }
  return false;
}

function score(faq) {
  const queryTokens = tokenize(query);
  // Keywords pueden ser frases separadas por coma — tokenizamos cada una.
  const keywordsRaw = String(faq.Keywords || '').split(/[,;]+/).map(k => k.trim()).filter(Boolean);
  let keywordScore = 0;
  const matchedKws = new Set();
  for (const kwRaw of keywordsRaw) {
    if (matchedKws.has(kwRaw)) continue;
    const kwTokens = tokenize(kwRaw);
    if (kwTokens.length === 0) continue;
    if (matchTokens(queryTokens, kwTokens)) {
      keywordScore += 2;
      matchedKws.add(kwRaw);
    }
  }
  // Score por match con la propia pregunta del FAQ
  const preguntaTokens = tokenize(faq['Pregunta'] || '').filter(t => t.length >= 4);
  let preguntaScore = 0;
  for (const pt of preguntaTokens) {
    const pts = stem(pt);
    for (const qt of queryTokens) {
      const qts = stem(qt);
      if (qt === pt || qts === pts) { preguntaScore += 1; break; }
    }
  }
  const baseScore = keywordScore + preguntaScore;
  // Categoria_hint solo da boost si YA hay match real
  const cat = normalize(faq['Categoría']);
  const catHint = normalize(categoria);
  const categoriaBoost = (catHint && baseScore > 0 && cat.includes(catHint)) ? 3 : 0;
  return baseScore + categoriaBoost;
}

// Threshold: requiere >= 2 puntos REALES (de keyword/pregunta match, no de boost).
const scored = faqs.map(f => ({ faq: f, s: score(f) }))
  .filter(x => x.s >= 2)
  .sort((a, b) => b.s - a.s);

if (scored.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    data: null,
    message_to_agent: `No encontré una FAQ que matchee "${query}". Si es algo común, sugerile al cliente que llame a 4342-5742 o derivá al comercial. Si la consulta es genérica, agregala a la tabla FAQs de Airtable.`,
    trace_id: $execution.id
  } }];
}

const best = scored[0].faq;
return [{ json: {
  status: 'RESOLVED',
  data: {
    respuesta_corta: best['Respuesta corta'] || '',
    categoria: best['Categoría'] || '',
    pregunta_matched: best['Pregunta'] || ''
  },
  message_to_agent: `Respuesta encontrada en categoría "${best['Categoría']}". Integrala natural a tu respuesta.`,
  trace_id: $execution.id
} }];
